async () => {
  const urls = [
    'https://bitbucket.org/!api/2.0/repositories/healshealthcare/csx-web/pullrequests/570',
    '/!api/2.0/repositories/healshealthcare/csx-web/pullrequests/570',
    'https://bitbucket.org/healshealthcare/csx-web/pull-requests/570/diff'
  ];
  const out = {};
  for (const u of urls) {
    try {
      const r = await fetch(u, {credentials:'include'});
      out[u] = {status: r.status, ct: r.headers.get('content-type'), text: (await r.text()).slice(0, 1500)};
    } catch (e) {
      out[u] = {error: String(e)};
    }
  }
  const redux = window.__INITIAL_STATE__ || window.__APP_INITIAL_STATE__ || null;
  return {out, reduxKeys: redux && Object.keys(redux), title: document.title};
}

